// ─── Parse WhatsApp Business API Payload ───────────────────
// Meta sends messages in a deeply nested structure.
// This node unwraps it and checks if it's a real text message.

const body = $input.first().json;

const entry   = body.entry?.[0];
const change  = entry?.changes?.[0];
const value   = change?.value;

// If there are no messages in this event, bail out gracefully
if (!value?.messages || value.messages.length === 0) {
  return [{ json: { isMessage: false, reason: 'no_messages_in_payload' } }];
}

const message = value.messages[0];
const contact = value.contacts?.[0];

// Only process text messages (ignore images, audio, reactions, etc.)
if (message.type !== 'text') {
  return [{ json: { isMessage: false, reason: `unsupported_type:${message.type}` } }];
}

// ── Extract core fields ──────────────────────────────────────
const senderPhone = message.from;                              // e.g. "14075551234"
const senderName  = contact?.profile?.name || 'Unknown';      // Display name from WA profile
const messageBody = message.text?.body || '';
const messageId   = message.id;
const receivedAt  = new Date(parseInt(message.timestamp) * 1000).toISOString();

return [{
  json: {
    isMessage:   true,
    phone:       senderPhone,
    name:        senderName,
    message:     messageBody,
    messageId:   messageId,
    receivedAt:  receivedAt,
    rawPayload:  JSON.stringify(body)
  }
}];

// ─── Extract & Classify Lead Data ──────────────────────────
// Runs keyword detection on the message body to guess
// what type of project the person is reaching out about.
// Extend the keyword lists below to fit your services.

const data    = $input.first().json;
const message = (data.message || '').toLowerCase();

// ── Project type detection ───────────────────────────────────
let projectType = 'General Inquiry';   // default

if (message.includes('shopify') || message.includes('store') || message.includes('ecomm')) {
  projectType = 'Shopify / E-Commerce';
} else if (message.includes('web app') || message.includes('webapp') || message.includes('application')) {
  projectType = 'Web App Development';
} else if (message.includes('website') || message.includes('landing page') || message.includes('portfolio')) {
  projectType = 'Website';
} else if (message.includes('automation') || message.includes('n8n') || message.includes('workflow') || message.includes('zapier')) {
  projectType = 'Automation / n8n';
} else if (message.includes('consult') || message.includes('advice') || message.includes('strategy')) {
  projectType = 'Consulting';
} else if (message.includes('pallet') || message.includes('furniture') || message.includes('wood')) {
  projectType = 'DIY / Custom Build';
} else if (message.includes('music') || message.includes('merch') || message.includes('print') || message.includes('sticker')) {
  projectType = 'Robot Fantome / Merch';
}

// ── Build clean notes string ─────────────────────────────────
const preview = data.message.slice(0, 300);
const notes   = `Auto-intake via WhatsApp.\nMessage preview: "${preview}"${data.message.length > 300 ? '...' : ''}`;

return [{
  json: {
    ...data,
    projectType,
    status:  'new',
    source:  'whatsapp',
    notes
  }
}];
